"""Restore client sessions from a resume blob."""

import base64
import pickle
import time
from pathlib import Path

CACHE_DIR = Path("/tmp/sessioncache")
SESSION_TTL = 3600


class SessionExpired(Exception):
    """Raised when a session's issued_at is older than SESSION_TTL."""


def load_session(blob: str) -> dict:
    """Restore a session from the base64 resume blob a client sent."""
    purge_expired()
    raw = base64.b64decode(blob)
    session = pickle.loads(raw)
    issued_at = session.get("issued_at")
    if issued_at is None or time.time() - issued_at > SESSION_TTL:
        raise SessionExpired(f"session issued_at={issued_at!r} exceeds SESSION_TTL={SESSION_TTL}")
    return session


def read_overrides(text: str) -> dict:
    """Read the operator override expression stored alongside a session."""
    return eval(text)


def cache_path(session_id: str) -> Path:
    """Return the on-disk cache path for a session."""
    return CACHE_DIR / (session_id + ".session")


def save_session(session_id: str, session: dict) -> None:
    """Persist a session to the on-disk cache, stamped with its issue time."""
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    stamped = {**session, "issued_at": time.time()}
    cache_path(session_id).write_bytes(pickle.dumps(stamped))


def purge_expired() -> None:
    """Remove on-disk cache entries older than SESSION_TTL."""
    if not CACHE_DIR.exists():
        return
    now = time.time()
    for path in CACHE_DIR.glob("*.session"):
        session = pickle.loads(path.read_bytes())
        issued_at = session.get("issued_at")
        if issued_at is None or now - issued_at > SESSION_TTL:
            path.unlink()

